/** The build's version, `2.YYYYMMDD.N.PR`, defined by vite.config.ts at build time (see src/lib/version.ts). */
declare const __ONOSENDAI_VERSION__: string
/** The build's id, the commit it was built from, defined by vite.config.ts; the same id /version.json names (src/lib/chainRulesEpoch.ts). */
declare const __ONOSENDAI_BUILD__: string
/** The app's simple version, `2.1` for package.json "2.1.0" (src/lib/version.ts simpleVersion), defined by vite.config.ts; empty when it is not plain numbers. */
declare const __ONOSENDAI_APP_VERSION__: string
